insert into public.categories (id, name, slug, description, image_path, sort_order) values
  ('bb6f077c-d902-50aa-a126-bc75ac95ce93', 'Living', 'living', 'Lounge chairs, sofas, side tables and lighting for rooms made for slowing down.', 'categories/living.webp', 0),
  ('a4dcb23e-cf96-5523-9d01-fec74c3890b0', 'Kitchen & Dining', 'kitchen-dining', 'Stoneware, glass and table linen for everyday meals and long dinners alike.', 'categories/kitchen-dining.webp', 1),
  ('0333658c-752b-577d-ada8-d213ddc23297', 'Bedroom', 'bedroom', 'Stonewashed linen, organic cotton and quiet furniture for restful rooms.', 'categories/bedroom.webp', 2),
  ('e6f8717c-1b0d-5e7a-a709-e3021a01fa88', 'Bath', 'bath', 'Plush towels, robes and considered accessories for a calmer bathroom.', 'categories/bath.webp', 3),
  ('253c7483-2c30-5c32-90b4-d8745757c79e', 'Decor', 'decor', 'Vases, candles, baskets and mirrors: the finishing layer of a home.', 'categories/decor.webp', 4)
insert into public.products (id, category_id, name, slug, short_description, description, brand, specifications, status, is_featured, published_at) values
  ('b53ea87a-3278-5c7b-b065-8370b8364726', 'bb6f077c-d902-50aa-a126-bc75ac95ce93', 'Arden Lounge Chair', 'arden-lounge-chair', 'A low, enveloping swivel chair in textured upholstery on a solid oak base.', 'Arden is built for the slow hours: a deep, gently reclined seat and a high back that wraps around you. The upholstery is a dense, hard-wearing weave, and the four-star base is turned from solid FSC-certified oak. It swivels smoothly through a full turn, so it can face the window or the conversation.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"W 74 × D 78 × H 82 cm · seat height 42 cm"},{"label":"Materials","value":"Solid oak base, high-resilience foam, upholstery from 89% recycled polyester"},{"label":"Care","value":"Vacuum regularly; spot clean with a damp cloth"},{"label":"Lead time","value":"Ships in 1–2 weeks"}]'::jsonb, 'active', true, '2026-10-01T00:00:00.000Z'),
  ('5405bf76-7258-5e05-b946-5e66d99e3a37', 'bb6f077c-d902-50aa-a126-bc75ac95ce93', 'Lune Two-Seater Sofa', 'lune-two-seater-sofa', 'A compact sofa with soft, rounded arms and feather-wrapped cushions.', 'Lune fits generous comfort into a footprint made for apartments. Feather-wrapped seat cushions keep their shape, the rounded arms are just the right height for leaning, and the slim oak legs lift it off the floor so the room feels lighter. The covers are removable and washable.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"W 176 × D 88 × H 80 cm · seat depth 58 cm"},{"label":"Materials","value":"Kiln-dried hardwood frame, feather-wrapped foam, cotton-linen cover"},{"label":"Care","value":"Removable covers, cool wash or dry clean"},{"label":"Lead time","value":"Ships in 3–4 weeks"}]'::jsonb, 'active', true, '2026-09-28T00:00:00.000Z'),
  ('0c41fbeb-b621-59de-b4ed-222cca67f0a7', 'bb6f077c-d902-50aa-a126-bc75ac95ce93', 'Fringed Cotton Throw', 'fringed-cotton-throw', 'A heavyweight waffle-knit throw with hand-knotted fringe.', 'Woven from long-staple cotton in a deep waffle texture, this throw is warm without weight and only softens with washing. The fringe is knotted by hand at each end. Drape it over a chair, fold it at the foot of the bed, or keep it within reach of the sofa.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"130 × 170 cm plus 8 cm fringe"},{"label":"Materials","value":"100% long-staple cotton"},{"label":"Care","value":"Machine wash cold, line dry"}]'::jsonb, 'active', false, '2026-09-25T00:00:00.000Z'),
  ('377dd073-c4ab-510c-9652-2cf8aed492fd', 'bb6f077c-d902-50aa-a126-bc75ac95ce93', 'Halden Nesting Tables', 'halden-nesting-tables', 'Three solid-wood side tables that tuck neatly into one another.', 'Use them together as a stepped display, pull one out for a drink beside the sofa, or spread all three across a room when guests arrive. Each table is made from solid wood with a waterfall edge that shows the grain running continuously from top to leg.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"Large W 50 × D 35 × H 45 cm; medium and small nest inside"},{"label":"Materials","value":"Solid FSC-certified hardwood, hardwax oil finish"},{"label":"Care","value":"Wipe with a dry cloth; re-oil once a year"}]'::jsonb, 'active', false, '2026-09-22T00:00:00.000Z'),
  ('134db53e-5b7b-5d95-a26f-e579a4fe2f3d', 'bb6f077c-d902-50aa-a126-bc75ac95ce93', 'Pleat Floor Lamp', 'pleat-floor-lamp', 'A slender floor lamp with a hand-pleated linen shade and a warm, diffused glow.', 'The shade is pleated by hand from natural linen, so the light it gives is soft and even, more glow than glare. A slim powder-coated stem and a weighted base keep it steady without taking up floor space. It comes with an inline dimmer.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"H 150 cm · shade Ø 38 cm"},{"label":"Materials","value":"Linen shade, powder-coated steel, weighted base"},{"label":"Bulb","value":"E26/E27, max 60 W LED (not included)"}]'::jsonb, 'active', false, '2026-09-19T00:00:00.000Z'),
  ('c3e587e0-b916-577b-a850-4db36d355192', 'a4dcb23e-cf96-5523-9d01-fec74c3890b0', 'Terra Stoneware Dinner Plates, Set of 4', 'terra-stoneware-dinner-plates', 'Wheel-thrown stoneware plates with a soft, satin-matte glaze.', 'Each plate is thrown on the wheel and finished with a satin glaze that feels almost like stone under the hand. Slight variations in shape and tone are part of the character. They''re dishwasher and microwave safe, and sturdy enough for every day.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"Ø 27 cm · set of 4"},{"label":"Materials","value":"High-fired stoneware, lead-free glaze"},{"label":"Care","value":"Dishwasher and microwave safe"}]'::jsonb, 'active', true, '2026-09-16T00:00:00.000Z'),
  ('60b5ce00-da71-58bd-a6cd-b10964c49290', 'a4dcb23e-cf96-5523-9d01-fec74c3890b0', 'Kiln Stoneware Tumbler', 'kiln-stoneware-tumbler', 'A handleless stoneware cup with an exposed clay foot.', 'Made for coffee, tea, water or wine, the tumbler sits comfortably in the hand. The glaze stops short of the base to reveal the raw, toasted clay, and every piece carries its own speckling from the kiln.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"Ø 8 × H 11 cm · 300 ml"},{"label":"Materials","value":"Speckled stoneware, food-safe glaze"},{"label":"Care","value":"Dishwasher safe"}]'::jsonb, 'active', false, '2026-09-13T00:00:00.000Z'),
  ('f765a2db-8b5e-5bc5-b916-5fd6dcd82541', 'a4dcb23e-cf96-5523-9d01-fec74c3890b0', 'Pinch Espresso Cups, Set of 4', 'pinch-espresso-cups', 'Small hand-pinched porcelain cups with a raw, tactile finish.', 'Shaped by hand rather than cast, each cup holds a double espresso and stacks neatly when not in use. The unglazed exterior is soft and chalky, and the inside is glazed for easy cleaning.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"Ø 6.5 × H 5.5 cm · 90 ml · set of 4"},{"label":"Materials","value":"Porcelain, glazed interior"},{"label":"Care","value":"Hand wash recommended"}]'::jsonb, 'active', false, '2026-09-10T00:00:00.000Z'),
  ('946cc8b6-7e0a-5c41-aff6-e4bf8bc8c720', 'a4dcb23e-cf96-5523-9d01-fec74c3890b0', 'Olive Wood Serving Board', 'olive-wood-serving-board', 'A paddle board carved from a single piece of olive wood.', 'Olive wood is dense, naturally antibacterial and dramatically grained, so no two boards look alike. Use it for bread, cheese or as a trivet at the table. The carved handle has a hole for hanging.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"Medium 38 × 20 cm · Large 48 × 26 cm"},{"label":"Materials","value":"Solid olive wood, food-safe oil"},{"label":"Care","value":"Hand wash, dry upright, oil occasionally"}]'::jsonb, 'active', false, '2026-09-07T00:00:00.000Z'),
  ('87daacfd-9423-506a-b124-df8eebfd7a15', 'a4dcb23e-cf96-5523-9d01-fec74c3890b0', 'Ribbed Glass Carafe', 'ribbed-glass-carafe', 'A mouth-blown carafe with fine vertical ribs that catch the light.', 'Mouth-blown from lead-free borosilicate glass, the carafe is light, heat-resistant and pours cleanly without dripping. Its fine ribbing scatters light across the table. It holds a full litre.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"Ø 10 × H 24 cm · 1 L"},{"label":"Materials","value":"Mouth-blown borosilicate glass"},{"label":"Care","value":"Dishwasher safe"}]'::jsonb, 'active', false, '2026-09-04T00:00:00.000Z'),
  ('3199ba6c-8cb6-5230-b35c-ff576aaefcf9', 'a4dcb23e-cf96-5523-9d01-fec74c3890b0', 'Washed Linen Napkins, Set of 4', 'washed-linen-napkins', 'Generously sized stonewashed linen napkins, soft from the first use.', 'Cut from European flax linen and stonewashed for a lived-in softness, these napkins are made to be used and washed again and again. Mitred corners and a narrow hem keep them neat.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"45 × 45 cm · set of 4"},{"label":"Materials","value":"100% European flax linen, OEKO-TEX certified"},{"label":"Care","value":"Machine wash warm, tumble dry low"}]'::jsonb, 'active', false, '2026-09-01T00:00:00.000Z'),
  ('64f6ff71-9fc5-5187-a332-ffe748ab0020', '0333658c-752b-577d-ada8-d213ddc23297', 'Stonewashed Linen Duvet Cover', 'stonewashed-linen-duvet-cover', 'Breathable French flax linen, stonewashed for a relaxed, rumpled softness.', 'Linen keeps you cool in summer and warm in winter, and it gets softer with every wash. Ours is woven from French flax and stonewashed so it feels broken-in from the first night. It has hidden coconut-shell buttons and corner ties to keep the duvet in place.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"Full/Queen 228 × 228 cm · King 264 × 228 cm"},{"label":"Materials","value":"100% French flax linen, 165 gsm, OEKO-TEX certified"},{"label":"Care","value":"Machine wash warm, tumble dry low"}]'::jsonb, 'active', true, '2026-08-29T00:00:00.000Z'),
  ('ca0fbf10-dc9c-5357-be73-33f50fed59d0', '0333658c-752b-577d-ada8-d213ddc23297', 'Organic Cotton Sheet Set', 'organic-cotton-sheet-set', 'Crisp, cool percale in GOTS-certified organic cotton.', 'Percale is woven one-over-one for a matte, crisp hand that stays cool all night. The set includes a fitted sheet with deep pockets, a flat sheet and two pillowcases, all made from GOTS-certified organic cotton.', 'ShopSphere Studio', '[{"label":"Includes","value":"Fitted sheet, flat sheet, 2 pillowcases"},{"label":"Materials","value":"100% organic cotton percale, 300 thread count, GOTS certified"},{"label":"Care","value":"Machine wash warm, tumble dry low"}]'::jsonb, 'active', false, '2026-08-26T00:00:00.000Z'),
  ('cae8bf32-8118-53ba-be5e-9e4e1b346a7a', '0333658c-752b-577d-ada8-d213ddc23297', 'Alder Bedside Table', 'alder-bedside-table', 'A compact bedside table with a soft-close drawer and an open shelf.', 'Alder keeps the essentials close: a soft-close drawer for the things you''d rather not see and an open shelf for the book you''re reading. The frame is solid oak, finished with a matte lacquer that resists water rings.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"W 45 × D 35 × H 55 cm"},{"label":"Materials","value":"Solid oak frame, oak veneer drawer, matte lacquer"},{"label":"Assembly","value":"Legs attach in minutes; tools included"}]'::jsonb, 'active', false, '2026-08-23T00:00:00.000Z'),
  ('4ab06db0-92bc-54da-969f-deefff1f012c', '0333658c-752b-577d-ada8-d213ddc23297', 'Halo Table Lamp', 'halo-table-lamp', 'A turned walnut base under a drum shade of natural linen.', 'Halo''s base is turned from a single piece of walnut and topped with a linen drum shade that softens the light into a warm halo. It''s a natural fit for a bedside, a console or a reading corner.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"H 42 cm · shade Ø 26 cm"},{"label":"Materials","value":"Solid walnut, linen shade, braided fabric cord"},{"label":"Bulb","value":"E26/E27, max 40 W LED (not included)"}]'::jsonb, 'active', true, '2026-08-20T00:00:00.000Z'),
  ('ff0ba476-21cb-51d3-ba8a-84687057cc49', 'e6f8717c-1b0d-5e7a-a709-e3021a01fa88', 'Cloud Cotton Bathrobe', 'cloud-cotton-bathrobe', 'A plush, hotel-weight robe in looped Turkish cotton.', 'Heavy enough to feel indulgent and absorbent enough to replace a towel, the robe is woven in Turkey from long-staple cotton. It has a shawl collar, deep pockets and a belt that stays tied.', 'ShopSphere Studio', '[{"label":"Sizing","value":"S/M fits UK 6–12 / US 2–8 · L/XL fits UK 14–20 / US 10–16"},{"label":"Materials","value":"100% Turkish cotton terry, 450 gsm"},{"label":"Care","value":"Machine wash warm, tumble dry"}]'::jsonb, 'active', false, '2026-08-17T00:00:00.000Z'),
  ('a100f37a-8d96-52bf-ab42-37b9f59e5289', 'e6f8717c-1b0d-5e7a-a709-e3021a01fa88', 'Plush Cotton Bath Towel', 'plush-cotton-bath-towel', 'Dense, thirsty towels in heavyweight Egyptian cotton.', 'Woven from Egyptian cotton with long, absorbent loops, these towels feel substantial and dry quickly. A herringbone band at each end adds a quiet detail.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"Hand 50 × 90 cm · Bath 70 × 140 cm"},{"label":"Materials","value":"100% Egyptian cotton, 650 gsm"},{"label":"Care","value":"Machine wash warm, tumble dry; avoid fabric softener"}]'::jsonb, 'active', false, '2026-08-14T00:00:00.000Z'),
  ('9aab0b1b-f4d9-5a53-a88c-f4bbdfa451f1', 'e6f8717c-1b0d-5e7a-a709-e3021a01fa88', 'Chenille Bath Mat', 'chenille-bath-mat', 'A deep-pile cotton chenille mat that''s soft underfoot and quick to dry.', 'Thick chenille loops soak up water and feel wonderful under bare feet. A non-slip latex-free backing keeps it in place on tile, and it machine washes without losing its loft.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"50 × 80 cm"},{"label":"Materials","value":"100% cotton chenille, non-slip backing"},{"label":"Care","value":"Machine wash warm, tumble dry low"}]'::jsonb, 'active', false, '2026-08-11T00:00:00.000Z'),
  ('b324229f-fa5d-5246-a00e-9dd95f703f71', 'e6f8717c-1b0d-5e7a-a709-e3021a01fa88', 'Ribbed Glass Soap Dispenser', 'ribbed-glass-soap-dispenser', 'A refillable ribbed glass dispenser with a brushed-brass pump.', 'Swap single-use bottles for something you''ll want to keep on display. The heavy ribbed glass is tinted a soft smoke, and the brushed-brass pump resists water spots. It holds 350 ml of hand or dish soap.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"Ø 7.5 × H 18 cm · 350 ml"},{"label":"Materials","value":"Tinted glass, brushed brass-finish pump"},{"label":"Care","value":"Hand wash"}]'::jsonb, 'active', false, '2026-08-08T00:00:00.000Z'),
  ('ddd61bd3-6d46-5333-9362-0f1b366ee6c7', '253c7483-2c30-5c32-90b4-d8745757c79e', 'Ridge Ceramic Vase', 'ridge-ceramic-vase', 'A full-bodied matte vase that stands on its own or with a single stem.', 'Ridge takes its shape from traditional storage jars: a wide shoulder, a narrow foot and a small collar at the neck. The matte glaze is waterproof inside, so it holds fresh flowers as well as dried branches.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"Medium H 25 cm · Large H 36 cm"},{"label":"Materials","value":"Stoneware, matte glaze, glazed interior"},{"label":"Care","value":"Wipe clean; not dishwasher safe"}]'::jsonb, 'active', true, '2026-08-05T00:00:00.000Z'),
  ('07c4479c-7797-5bc0-a72a-4fa6dc5f8f2c', '253c7483-2c30-5c32-90b4-d8745757c79e', 'Ribbed Pillar Candle', 'ribbed-pillar-candle', 'An unscented, hand-poured pillar candle with a fluted profile.', 'Poured by hand from a blend of rapeseed and coconut wax, these candles burn slowly and cleanly. They''re unscented, so they''ll sit happily on a dinner table, and the fluted sides cast soft shadows as they burn.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"Small Ø 7 × H 10 cm · Tall Ø 7 × H 15 cm"},{"label":"Burn time","value":"Small approx. 30 hours · Tall approx. 45 hours"},{"label":"Materials","value":"Rapeseed and coconut wax, cotton wick"}]'::jsonb, 'active', false, '2026-08-02T00:00:00.000Z'),
  ('a27d8056-bba4-5e51-b0bd-044c69c4809c', '253c7483-2c30-5c32-90b4-d8745757c79e', 'Tidal Woven Baskets, Set of 3', 'tidal-woven-baskets', 'Three nesting baskets hand-woven from natural palm leaf.', 'Hand-woven in a herringbone pattern from sun-dried palm leaf, the baskets nest for storage and work alone for throws, toys, plants or fruit. Every set is made by a small cooperative of weavers.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"Ø 22, 28 and 34 cm"},{"label":"Materials","value":"Natural palm leaf"},{"label":"Care","value":"Keep dry; brush off dust"}]'::jsonb, 'active', false, '2026-07-30T00:00:00.000Z'),
  ('f24c9acf-14ef-5ef2-a643-42bb82bdcc6f', '253c7483-2c30-5c32-90b4-d8745757c79e', 'Linden Round Mirror', 'linden-round-mirror', 'A clean round mirror in a slim solid-oak frame.', 'A mirror that brightens a hallway or bathroom without competing with the rest of the room. The frame is solid oak, finished with a clear matte oil, and the glass is copper-free for a long, clear life.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"Ø 60 cm or Ø 80 cm · frame depth 3 cm"},{"label":"Materials","value":"Solid oak frame, copper-free mirror glass"},{"label":"Mounting","value":"Fixings included; hangs from a single hook"}]'::jsonb, 'active', false, '2026-07-27T00:00:00.000Z'),
  ('26efccfd-b4e5-55a1-9cda-7b3f4c57001a', '253c7483-2c30-5c32-90b4-d8745757c79e', 'Travertine Bookends', 'travertine-bookends', 'A pair of solid travertine bookends. Coming soon.', 'Cut from honed travertine with a slight natural pitting, the bookends are heavy enough to hold a full shelf. Draft product: visible to admins only until photography is ready.', 'ShopSphere Studio', '[{"label":"Dimensions","value":"W 12 × D 10 × H 15 cm each"},{"label":"Materials","value":"Honed travertine, felt base"}]'::jsonb, 'draft', false, null),
  ('0a7b8d13-a835-577f-945a-11996dafeecc', 'bb6f077c-d902-50aa-a126-bc75ac95ce93', 'Ivory Fringed Wool Rug', 'ivory-fringed-wool-rug', 'A hand-knotted wool rug in soft ivory with a tonal border and knotted fringe.', 'Knotted by hand from undyed New Zealand wool, this rug has a low, dense pile that feels soft underfoot and wears beautifully. A quiet tonal border frames the field, and the fringe is finished by hand at each end.
