  ('c389780c-0fd3-5ef5-be12-c4cf3ba76cd8', 'ff0ba476-21cb-51d3-ba8a-84687057cc49', 'products/cloud-cotton-bathrobe/1.webp', 'Two Cloud Cotton Bathrobes hanging in a warm-lit bathroom', 0),
  ('31c66f84-f3ca-53ff-a753-98700006cf4b', 'a100f37a-8d96-52bf-ab42-37b9f59e5289', 'products/plush-cotton-bath-towel/1.webp', 'Plush Cotton Bath Towel in stone, rolled', 0),
